import * as orig from 'C:/Users/user/AppData/Local/Temp/skill-eval-L6y9WY/src/module.ts';
import * as next from 'C:/Users/user/AppData/Local/Temp/skill-eval-L6y9WY/out/module.ts';
import assert from 'node:assert/strict';

const NAMES = ['kim','lee','park','jung','choi'];
const rint = (a,b) => a + Math.floor(Math.random()*(b-a+1));
const pick = a => a[rint(0,a.length-1)];
const ser = v => JSON.stringify(v, (k, x) => x === undefined ? '__undef__' : x);
let n = 0;
function check(fname, args) {
  const a = orig[fname](...args), b = next[fname](...args);
  assert.equal(ser(b), ser(a), `${fname} mismatch on ${ser(args)}`);
  assert.deepEqual(Object.keys(b), Object.keys(a)); // key order too
  n++;
}
// example inputs
check('doubled', [{jung:43,park:16}]); check('doubled', [{}]);
check('byNameKey', [[]]);
const rowsEx = [{"id":9,"name":"kim","age":34},{"id":3,"name":"park","age":57},{"id":2,"name":"jung","age":58},{"id":1,"name":"lee","age":47},{"id":5,"name":"park","age":30},{"id":3,"name":"lee","age":40},{"id":0,"name":"park","age":19},{"id":0,"name":"lee","age":24},{"id":0,"name":"kim","age":51},{"id":4,"name":"park","age":45},{"id":7,"name":"kim","age":37},{"id":9,"name":"lee","age":51}];
check('byNameKey', [rowsEx]);
check('toLookup', [[["kim",57],["jung",57],["kim",72],["choi",59],["jung",53],["lee",28]]]);
check('toLookup', [[["kim",35],["lee",1],["jung",41],["park",11],["jung",39],["jung",92]]]);
// random in-range
for (let t = 0; t < 20000; t++) {
  const obj = {}; const k = rint(0,5); for (let i=0;i<k;i++) obj[pick(NAMES)] = rint(-5,99);
  check('doubled', [obj]);
  const rows = Array.from({length: rint(0,12)}, () => ({id: rint(0,9), name: pick(NAMES), age: rint(18,60)}));
  check('byNameKey', [rows]);
  const pairs = Array.from({length: rint(0,8)}, () => [pick(NAMES), rint(-5,99)]);
  check('toLookup', [pairs]);
}
console.log('all equal, checks:', n);
EOF
