require('C:/Users/user/AppData/Local/Temp/skill-eval-L6y9WY/node_modules/esbuild').build({entryPoints:['eq.mjs'],bundle:true,format:'esm',platform:'node',outfile:'eq.bundle.mjs',absWorkingDir:process.cwd(),logLevel:'error'}).then(()=>console.log('bundled'))" && node eq.bundle.mjs

